import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Inline CUDA/C++ code for custom operators
shuff_ops_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

// -----------------------------------------
// Channel Shuffle Kernel
// -----------------------------------------
__global__ void channel_shuffle_kernel(const float* __restrict__ in, float* __restrict__ out, 
                                       int b, int c, int h, int w, int groups, int chg) {
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    int total = b * c * h * w;
    if (index < total) {
        int tmp = index;
        int w_idx = tmp % w;
        tmp /= w;
        int h_idx = tmp % h;
        tmp /= h;
        int c2 = tmp % c;
        tmp /= c;
        int b_idx = tmp;

        int j = c2 % groups;
        int k = c2 / groups;
        int c1 = j * chg + k;

        int in_index = ((b_idx * c + c1) * h + h_idx) * w + w_idx;
        out[index] = in[in_index];
    }
}

torch::Tensor channel_shuffle_cuda(torch::Tensor x, int groups) {
    auto b = x.size(0);
    auto c = x.size(1);
    auto h = x.size(2);
    auto w = x.size(3);

    int chg = c / groups;
    auto out = torch::empty_like(x);

    int total = b * c * h * w;
    int block_size = 256;
    int grid_size = (total + block_size - 1) / block_size;

    channel_shuffle_kernel<<<grid_size, block_size>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        b, c, h, w, groups, chg
    );
    return out;
}

// -----------------------------------------
// Elementwise Add Kernel
// -----------------------------------------
__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::empty_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;
    elementwise_add_kernel<<<num_blocks, block_size>>>(
        a.data_ptr<float>(),
        b.data_ptr<float>(),
        out.data_ptr<float>(),
        size
    );
    return out;
}

// -----------------------------------------
// ReLU Kernel
// -----------------------------------------
__global__ void relu_kernel(float* data, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        if (data[idx] < 0.0f) {
            data[idx] = 0.0f;
        }
    }
}

torch::Tensor relu_cuda(torch::Tensor x) {
    auto out = x.clone();
    auto size = out.numel();
    int block_size = 256;
    int grid_size = (size + block_size - 1) / block_size;
    relu_kernel<<<grid_size, block_size>>>(out.data_ptr<float>(), size);
    return out;
}
""";

shuff_ops_header = r"""
torch::Tensor channel_shuffle_cuda(torch::Tensor x, int groups);
torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b);
torch::Tensor relu_cuda(torch::Tensor x);
""";

# Build extension
shuff_ops = load_inline(
    name="shuff_ops",
    cpp_sources=shuff_ops_header,
    cuda_sources=shuff_ops_source,
    functions=["channel_shuffle_cuda", "elementwise_add_cuda", "relu_cuda"],
    verbose=False,
)

# Custom ShuffleNet Unit using inline CUDA ops
class ShuffleNetUnitNew(nn.Module):
    def __init__(self, in_channels, out_channels, groups=3):
        super(ShuffleNetUnitNew, self).__init__()
        assert out_channels % 4 == 0
        self.groups = groups
        mid_channels = out_channels // 4

        self.conv1 = nn.Conv2d(in_channels, mid_channels, kernel_size=1, stride=1, padding=0, groups=groups, bias=False)
        self.bn1 = nn.BatchNorm2d(mid_channels)

        self.conv2 = nn.Conv2d(mid_channels, mid_channels, kernel_size=3, stride=1, padding=1, groups=mid_channels, bias=False)
        self.bn2 = nn.BatchNorm2d(mid_channels)

        self.conv3 = nn.Conv2d(mid_channels, out_channels, kernel_size=1, stride=1, padding=0, groups=groups, bias=False)
        self.bn3 = nn.BatchNorm2d(out_channels)

        if in_channels == out_channels:
            self.shortcut = nn.Sequential()
        else:
            self.shortcut = nn.Sequential(
                nn.Conv2d(in_channels, out_channels, kernel_size=1, stride=1, padding=0, bias=False),
                nn.BatchNorm2d(out_channels)
            )

    def forward(self, x):
        out = shuff_ops.relu_cuda(self.bn1(self.conv1(x)))
        out = self.bn2(self.conv2(out))
        out = shuff_ops.channel_shuffle_cuda(out, self.groups)
        out = shuff_ops.relu_cuda(self.bn3(self.conv3(out)))
        shortcut_out = self.shortcut(x)
        out = shuff_ops.elementwise_add_cuda(out, shortcut_out)
        return out

# New Model architecture using custom ShuffleNetUnit
class ModelNew(nn.Module):
    def __init__(self, num_classes=1000, groups=3, stages_repeats=[3, 7, 3], stages_out_channels=[24, 240, 480, 960]):
        super(ModelNew, self).__init__()
        self.conv1 = nn.Conv2d(3, stages_out_channels[0], kernel_size=3, stride=2, padding=1, bias=False)
        self.bn1 = nn.BatchNorm2d(stages_out_channels[0])
        self.maxpool = nn.MaxPool2d(kernel_size=3, stride=2, padding=1)

        self.stage2 = self._make_stage(stages_out_channels[0], stages_out_channels[1], stages_repeats[0], groups)
        self.stage3 = self._make_stage(stages_out_channels[1], stages_out_channels[2], stages_repeats[1], groups)
        self.stage4 = self._make_stage(stages_out_channels[2], stages_out_channels[3], stages_repeats[2], groups)

        self.conv5 = nn.Conv2d(stages_out_channels[3], 1024, kernel_size=1, stride=1, padding=0, bias=False)
        self.bn5 = nn.BatchNorm2d(1024)

        self.fc = nn.Linear(1024, num_classes)

    def _make_stage(self, in_channels, out_channels, repeats, groups):
        layers = []
        layers.append(ShuffleNetUnitNew(in_channels, out_channels, groups))
        for _ in range(1, repeats):
            layers.append(ShuffleNetUnitNew(out_channels, out_channels, groups))
        return nn.Sequential(*layers)

    def forward(self, x):
        x = shuff_ops.relu_cuda(self.bn1(self.conv1(x)))
        x = self.maxpool(x)

        x = self.stage2(x)
        x = self.stage3(x)
        x = self.stage4(x)

        x = shuff_ops.relu_cuda(self.bn5(self.conv5(x)))
        x = F.adaptive_avg_pool2d(x, (1, 1))
        x = x.view(x.size(0), -1)
        x = self.fc(x)
        return x

